() => {
  // Find the "Something went wrong" element and get its surrounding context
  const allElements = document.querySelectorAll('*');
  for (const el of allElements) {
    if (el.textContent === 'Something went wrong' && el.children.length === 0) {
      // Found the exact element
      const parent = el.parentElement;
      const grandParent = parent?.parentElement;
      const greatGrandParent = grandParent?.parentElement;

      // Get sibling cards for comparison
      const siblings = greatGrandParent ? Array.from(greatGrandParent.children).map(c => ({
        text: c.textContent?.substring(0, 100),
        className: c.className
      })) : [];

      return {
        element: { tag: el.tagName, class: el.className, text: el.textContent },
        parent: { tag: parent?.tagName, class: parent?.className, html: parent?.innerHTML?.substring(0, 500) },
        grandParent: { tag: grandParent?.tagName, class: grandParent?.className },
        greatGrandParent: { tag: greatGrandParent?.tagName, class: greatGrandParent?.className },
        siblingCount: siblings.length,
        siblings: siblings.slice(0, 15)
      };
    }
  }
  return 'not found';
}
